import AppKit
import CryptoKit
import ImageIO

/// 클립보드 한 시점의 내용
struct PasteboardSnapshot {
    /// NSPasteboardItem별 (타입, 데이터) 목록. 다시 복사할 때 그대로 되돌려 쓴다.
    var items: [[PasteboardEntry]]
    var kind: ClipItem.Kind
    var text: String
    var contentHash: String
    var thumbnailPNG: Data?
}

enum PasteboardCodec {
    /// 비밀번호 관리자 등이 "기록하지 말 것"으로 표시할 때 쓰는 타입 (nspasteboard.org 관례)
    static let ignoredMarkerTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "net.antelle.keeweb",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// 전체 크기가 maxSnapshotBytes를 넘으면 이 타입들만 남긴다
    static let essentialTypes: Set<String> = [
        NSPasteboard.PasteboardType.string.rawValue,
        NSPasteboard.PasteboardType.rtf.rawValue,
        NSPasteboard.PasteboardType.html.rawValue,
        NSPasteboard.PasteboardType.fileURL.rawValue,
        NSPasteboard.PasteboardType.URL.rawValue,
        NSPasteboard.PasteboardType.png.rawValue,
        NSPasteboard.PasteboardType.tiff.rawValue,
    ]

    static let imageTypes: [NSPasteboard.PasteboardType] = [
        .png, .tiff, .init("public.jpeg"), .init("public.heic"), .init("com.compuserve.gif"),
    ]

    static let maxSnapshotBytes = 32 * 1024 * 1024
    static let maxStoredTextLength = 20_000
    /// 이보다 화소가 많은 이미지는 미리보기를 만들지 않는다 (디코딩 메모리 폭증 방지)
    static let maxThumbnailSourcePixels = 100_000_000

    static func snapshot(of pasteboard: NSPasteboard) -> PasteboardSnapshot? {
        let changeCount = pasteboard.changeCount
        guard let pbItems = pasteboard.pasteboardItems, !pbItems.isEmpty else { return nil }
        let allTypes = Set(pbItems.flatMap { $0.types.map(\.rawValue) })
        guard allTypes.isDisjoint(with: ignoredMarkerTypes),
              let summary = summarize(pasteboard) else { return nil }

        let items = readItems(pbItems)
        // 읽는 도중 클립보드가 바뀌었으면(예: 비밀번호 관리자가 복사) 섞인 내용을 저장하지 않는다.
        // 바뀐 내용은 다음 확인 때 처음부터 다시 읽는다.
        guard !items.isEmpty, pasteboard.changeCount == changeCount else { return nil }
        return PasteboardSnapshot(items: items, kind: summary.kind, text: summary.text,
                                  contentHash: summary.hash, thumbnailPNG: summary.thumbnail)
    }

    @discardableResult
    static func write(_ items: [[PasteboardEntry]], to pasteboard: NSPasteboard) -> Bool {
        let pbItems = items.map { entries -> NSPasteboardItem in
            let pbItem = NSPasteboardItem()
            for entry in entries {
                pbItem.setData(entry.data, forType: NSPasteboard.PasteboardType(entry.type))
            }
            return pbItem
        }
        pasteboard.clearContents()
        return pasteboard.writeObjects(pbItems)
    }

    /// 목록에 보여줄 종류와 텍스트를 정한다. 파일 > 텍스트 > 이미지 순으로 본다.
    /// (엑셀처럼 텍스트와 미리보기 이미지를 함께 올리는 앱은 텍스트로 취급)
    private static func summarize(_ pasteboard: NSPasteboard) -> (kind: ClipItem.Kind, text: String, hash: String, thumbnail: Data?)? {
        let fileURLs = pasteboard.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL] ?? []
        if !fileURLs.isEmpty {
            let paths = fileURLs.map(\.path).joined(separator: "\n")
            return (.files, paths, sha256("files\n" + paths), nil)
        }
        if let string = pasteboard.string(forType: .string),
           !string.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return (.text, String(string.prefix(maxStoredTextLength)), sha256("text\n" + string), nil)
        }
        if let type = pasteboard.availableType(from: imageTypes),
           let data = pasteboard.data(forType: type) {
            let label = pixelSize(ofImageData: data).map { "이미지 \($0.width)×\($0.height)" } ?? "이미지"
            return (.image, label, sha256(data), thumbnailPNG(ofImageData: data))
        }
        return nil
    }

    private static func readItems(_ pbItems: [NSPasteboardItem]) -> [[PasteboardEntry]] {
        var items: [[PasteboardEntry]] = []
        for pbItem in pbItems {
            var entries: [PasteboardEntry] = []
            for type in pbItem.types where !isPromise(type.rawValue) {
                guard let data = pbItem.data(forType: type) else { continue }
                entries.append(PasteboardEntry(type: type.rawValue, data: data))
            }
            if !entries.isEmpty { items.append(entries) }
        }
        if byteCount(of: items) > maxSnapshotBytes {
            items = items.map { $0.filter { essentialTypes.contains($0.type) } }.filter { !$0.isEmpty }
            // 필수 타입만 남겨도 너무 크면 기록하지 않는다 (메모리·디스크 폭증 방지)
            if byteCount(of: items) > maxSnapshotBytes { return [] }
        }
        return items
    }

    private static func byteCount(of items: [[PasteboardEntry]]) -> Int {
        items.reduce(0) { total, entries in entries.reduce(total) { $0 + $1.data.count } }
    }

    /// 파일 프로미스는 원본 앱이 살아 있어야 의미가 있으므로 저장하지 않는다
    private static func isPromise(_ type: String) -> Bool {
        type.range(of: "promise", options: .caseInsensitive) != nil
    }

    static func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }

    static func sha256(_ string: String) -> String {
        sha256(Data(string.utf8))
    }

    /// 이미지 화소 크기. 헤더만 읽고 디코딩하지 않는다.
    static func pixelSize(ofImageData data: Data) -> (width: Int, height: Int)? {
        guard let source = CGImageSourceCreateWithData(data as CFData, nil),
              let properties = CGImageSourceCopyPropertiesAtIndex(source, 0, nil) as? [CFString: Any],
              let width = properties[kCGImagePropertyPixelWidth] as? Int,
              let height = properties[kCGImagePropertyPixelHeight] as? Int else { return nil }
        return (width, height)
    }

    static func thumbnailPNG(ofImageData data: Data, maxPixels: Int = 128,
                             maxSourcePixels: Int = maxThumbnailSourcePixels) -> Data? {
        guard let size = pixelSize(ofImageData: data),
              size.width > 0, size.height > 0, size.width * size.height <= maxSourcePixels,
              let source = CGImageSourceCreateWithData(data as CFData, nil) else { return nil }
        let options: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixels,
        ]
        guard let thumbnail = CGImageSourceCreateThumbnailAtIndex(source, 0, options as CFDictionary) else { return nil }
        return NSBitmapImageRep(cgImage: thumbnail).representation(using: .png, properties: [:])
    }
}
